const woodTextMat=new THREE.MeshStandardMaterial({map:woodTex,color:0xb7a17b,roughness:.95});

// ---------- Twilight village courtyard ----------
const floor=new THREE.Mesh(new THREE.PlaneGeometry(50,56),groundMat);floor.rotation.x=-Math.PI/2;floor.position.set(0,-.045,-7);floor.receiveShadow=true;scene.add(floor);
// Broken paving stones scattered into the dirt lane
const paving=mat(0x5a584d);for(let z=-24;z<12;z+=2.05)for(let x=-7;x<8;x+=2.1){if(Math.random()<.2)continue;const p=box(scene,x+(Math.random()-.5)*.24,.005,z+(Math.random()-.5)*.22,1.82+Math.random()*.25,.09,1.72+Math.random()*.25,paving,0,(Math.random()-.5)*.04,0);p.receiveShadow=true}
// Left-side old workshop: stone lower walls, timber upper wall, corrugated roof
box(scene,-12,2,-9,8,4,36,wallTextMat);box(scene,-12,4.2,-9,8.2,.3,36,mats.wood);
for(let z=-24;z<=8;z+=5){box(scene,-7.92,2,z,.2,4.2,.22,mats.wood2);box(scene,-7.92,4.15,z,.2,.17,.42,mats.rust)}
// tall dim windows and warm interior glow
for(let z=-22;z<=6;z+=7){box(scene,-7.88,2.4,z, .06,1.45,1.6,mats.darkStone);box(scene,-7.82,2.4,z,.06,1.14,1.25,mats.glass);box(scene,-7.75,2.4,z,.12,.08,1.65,mats.oldMetal);box(scene,-7.75,2.4,z,.12,1.48,.08,mats.oldMetal);box(scene,-7.7,2.4,z,.12,.08,1.25,mats.oldMetal)}
// corrugated roof panels with rusty ribs
box(scene,-11.8,4.35,-9,8.7,.3,36,mats.rust,0,0,.03);
for(let z=-26;z<10;z+=.75)box(scene,-11.8,4.55,z,8.6,.09,.07,mats.oldMetal,0,0,.03);
// Right side: plastered village houses / machine shed
box(scene,12,2.1,-11,7,4.2,32,wallTextMat);box(scene,12,4.25,-11,7.3,.28,32,mats.wood);
for(let z=-25;z<=1;z+=6){box(scene,8.47,2,z,.16,4.25,.25,mats.wood2);box(scene,8.47,4.1,z,.17,.15,.4,mats.rust)}
// pitched roof planes
box(scene,11.4,5.25,-11,4.2,.22,33,mats.rust,0,0,-.28);box(scene,14.7,5.25,-11,4.2,.22,33,mats.rust,0,0,.28);
for(let z=-26;z<5;z+=1){box(scene,11.5,5.37,z,4.25,.06,.065,mats.oldMetal,0,0,-.28);box(scene,14.6,5.37,z,4.25,.06,.065,mats.oldMetal,0,0,.28)}
// far end of the lane, low outbuildings and silhouette hills
box(scene,0,2,-25,24,4,2,wallTextMat);box(scene,0,4.4,-25,25,.35,2.5,mats.rust);
// doorway to a glowing workshop
box(scene,3.8,1.5,-23.9,2.1,3,.18,mats.darkStone);box(scene,3.8,1.5,-23.78,1.66,2.65,.08,mats.wood);box(scene,3.8,1.45,-23.7,.95,2.1,.07,mats.darkStone);
// exposed pipes and utility clutter
for(let x of [-7.3,8.4]){cyl(scene,x,2.8,-7,.11,.11,35,mats.metal,10,Math.PI/2);for(let z=-23;z<10;z+=4)box(scene,x+(x<0?.12:-.12),2.8,z,.18,.2,.2,mats.rust)}
// crates, oil drums, sacks
function crate(x,y,z,s=1){const group=new THREE.Group();group.position.set(x,y,z);scene.add(group);box(group,0,s*.48,0,s,s,s,woodTextMat);for(let i=-1;i<=1;i+=2){box(group,i*s*.38,s*.48,s*.505,.09,s*.95,.08,mats.wood2);box(group,i*s*.38,s*.48,-s*.505,.09,s*.95,.08,mats.wood2)}box(group,0,s*.48,s*.51,s*.92,.08,.08,mats.wood2);return group}
crate(-5.4,0,-5,1.15);crate(-4.3,0,-5.3,.7);crate(6.7,0,-18,1.3);crate(5.7,0,-18.3,.78);crate(-6.3,0,-20,.9);
const barrelMat=mat(0x494e49,.45,.65);for(const [x,z] of [[6.5,-7],[-5.7,-13],[7,-22]]){cyl(scene,x,.65,z,.42,.42,1.3,barrelMat,16);cyl(scene,x,.18,z,.435,.435,.08,mats.oldMetal,16);cyl(scene,x,1.12,z,.435,.435,.08,mats.oldMetal,16);box(scene,x,.68,z+.419,.5,.5,.025,mat(0x273b36,.3,.2))}
// utility wires suspended across yard
const wireMat=new THREE.LineBasicMaterial({color:0x252a27,transparent:true,opacity:.8});function wire(a,b,c){const curve=new THREE.CatmullRomCurve3([new THREE.Vector3(...a),new THREE.Vector3(...b),new THREE.Vector3(...c)]);scene.add(new THREE.Mesh(new THREE.TubeGeometry(curve,24,.025,5,false),wireMat))}
wire([-8,6,-18],[0,5.5,-12],[8,6,-5]);wire([-8,6,-3],[0,5.5,-8],[8,6,-15]);
// practical lamps with warm pools and metal shades
function lamp(x,z){box(scene,x,4.2,z,.09,1.2,.09,mats.metal);box(scene,x,4.8,z+.22,.56,.09,.62,mats.metal,-.3,0,0);const bulb=new THREE.Mesh(new THREE.SphereGeometry(.12,12,8),new THREE.MeshBasicMaterial({color:0xffb76b}));bulb.position.set(x,4.63,z+.22);scene.add(bulb);const l=new THREE.PointLight(0xffa65b,38,10,2);l.position.set(x,4.35,z+.3);scene.add(l);sphere(scene,x,4.35,z+.3,.2,new THREE.MeshBasicMaterial({color:0xffa653}),1,1,1)}
lamp(-7.3,-4);lamp(8.35,-14);lamp(-1,-22);
// little weeds between old stones
const weedMat=mat(0x3e4b38);for(let i=0;i<46;i++){const x=(Math.random()-.5)*15,z=2-Math.random()*26;if(Math.random()<.45)continue;for(let j=0;j<3;j++){const h=.16+Math.random()*.34;const w=box(scene,x+(Math.random()-.5)*.2,h/2,z+(Math.random()-.5)*.2,.025,h,.025,weedMat,0,Math.random()*1.8,0);w.castShadow=false}}

