wire([-8,6,-3],[0,5.5,-8],[8,6,-15]);

// ---------- Residents and modular requests ----------
const requests=[
 {name:'Aigerim',need:'My back hurts',thanks:'My shoulders feel lighter. Thank you.'},
 {name:'Serik',need:'I feel sick',thanks:'The warmth has settled my stomach. Rahmet.'},
 {name:'Mariya',need:'I am stressed',thanks:'I can breathe again. Thank you, Zhanat.'},
 {name:'Nurlan',need:'My knees are aching',thanks:'That feels much better. Rahmet, healer.'},
 {name:'Dana',need:'I have a heavy heart',thanks:'The quiet helped more than you know.'}
];
const residents=[];
function makeRequestSprite(text){const c=document.createElement('canvas');c.width=512;c.height=144;const g=c.getContext('2d');g.shadowColor='rgba(0,0,0,.4)';g.shadowBlur=14;g.fillStyle='rgba(15,18,16,.91)';g.beginPath();g.roundRect(8,8,496,126,12);g.fill();g.shadowBlur=0;g.strokeStyle='rgba(227,177,106,.65)';g.lineWidth=2;g.beginPath();g.roundRect(9,9,494,124,11);g.stroke();g.fillStyle='#e2aa68';g.beginPath();g.arc(42,72,17,0,Math.PI*2);g.fill();g.fillStyle='#2a1c12';g.font='600 25px sans-serif';g.textAlign='center';g.fillText('!',42,81);g.textAlign='left';g.fillStyle='#d5ccba';g.font='500 27px sans-serif';g.fillText(text,78,82);const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;const sp=new THREE.Sprite(new THREE.SpriteMaterial({map:t,transparent:true,depthWrite:false}));sp.scale.set(2.6,.74,1);return sp}
function resident(data,index,x,z){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);const coat=[mat(0x596257),mat(0x62544a),mat(0x59616a),mat(0x746550),mat(0x625e55)][index];
 // boots, legs, long coat silhouette
 for(const s of [-1,1]){box(g,s*.17,.14,.02,.22,.28,.38,mats.darkStone);box(g,s*.16,.63,0,.24,.82,.26,index%2?mats.wood:mat(0x353a36));}
 const body=box(g,0,1.35,0,.76,1.12,.42,coat);box(g,0,.97,-.02,.8,.42,.46,coat);box(g,0,1.91,0,.46,.48,.42,mats.skin);
 // neck, face and hair
 cyl(g,0,2.13,0,.12,.13,.2,mats.skin,10);sphere(g,0,2.48,0,.3,mats.skin,.84,1.08,.82);
 const hair=mat(index===1?0x51483c:0x39362f);sphere(g,0,2.66,-.025,.29,hair,.9,.57,.88);box(g,0,2.48,.235,.38,.07,.07,mat(0x302b26));
 // visible nose, eyes and collar
 sphere(g,0,2.44,.27,.055,mats.skin,.8,1,1.2);for(let s of [-1,1])sphere(g,s*.105,2.52,.244,.025,mat(0x25231f),1,1,1);
 box(g,0,1.88,.01,.49,.15,.46,index%2?mats.cream:mat(0x8c4f3c),.1,0,0);
 // hanging arms / sleeves, pivoted for relieved animation
 const arms=[];for(let s of [-1,1]){const pivot=new THREE.Group();pivot.position.set(s*.43,1.74,0);g.add(pivot);box(pivot,s*.035,-.44,0,.23,.82,.27,coat,0,0,s*.12);sphere(pivot,s*.04,-.87,.015,.12,mats.skin,.85,1,.8);arms.push(pivot)}
 // belt and little scarf
 box(g,0,1.03,.22,.58,.12,.045,mats.wood2);box(g,0,1.83,.24,.35,.23,.045,index===0?mat(0x95513b):mats.cream,.14,0,0);
 const icon=makeRequestSprite(data.need);icon.position.set(0,3.55,0);g.add(icon);
 const nameSprite=makeRequestSprite(data.name.toUpperCase());nameSprite.scale.set(1.45,.42,1);nameSprite.position.set(0,3.02,0);nameSprite.material.opacity=.83;g.add(nameSprite);
 const halo=new THREE.PointLight(0xffc275,1.4,2.5,2);halo.position.set(0,2.6,.2);g.add(halo);
 residents.push({group:g,body,arms,icon,nameSprite,data,index,healed:false,relief:0,baseY:0});
}
resident(requests[0],0,-3.1,-6.2);resident(requests[1],1,3.25,-9.6);resident(requests[2],2,-3.6,-14.2);resident(requests[3],3,3.8,-17.5);resident(requests[4],4,-.2,-21.6);

// ---------- First-person hands and healing ritual props ----------
const rig=new THREE.Group();camera.add(rig);scene.add(camera);
const sleeveMat=mat(0x4c554d),handMat=mat(0x98735b),bladeMetal=new THREE.MeshStandardMaterial({color:0xb1b5ab,metalness:.8,roughness:.22,emissive:0x8b2110,emissiveIntensity:.3});
const sword=new THREE.Group();rig.add(sword);sword.position.set(.56,-.44,-.82);sword.rotation.set(-.26,.04,-.15);
// blade directed forward/up when raised, brass guard, leather wrapped grip
const blade=new THREE.Mesh(new THREE.BoxGeometry(.115,.88,.045),bladeMetal);blade.position.y=.48;blade.castShadow=true;sword.add(blade);
const bladeTip=new THREE.Mesh(new THREE.ConeGeometry(.082,.22,4),bladeMetal);bladeTip.position.set(0,1.02,0);bladeTip.rotation.z=Math.PI;sword.add(bladeTip);
const guard=box(sword,0,.025,0,.37,.075,.12,mat(0x9a7441,.4,.7));guard.castShadow=false;
cyl(sword,0,-.31,0,.07,.085,.55,mats.wood2,8);for(let i=0;i<5;i++){const wrap=cyl(sword,0,-.48+i*.075,0,.088,.088,.025,mat(0x554539),8);wrap.rotation.x=Math.PI/2}
sphere(sword,0,-.61,0,.1,mat(0x9b7745,.4,.55));
const swordGlow=new THREE.PointLight(0xff4b1f,0,3,2);swordGlow.position.set(0,.8,.1);sword.add(swordGlow);
const bottle=new THREE.Group();rig.add(bottle);bottle.position.set(-.48,-.62,-.72);bottle.rotation.set(.16,.18,-.18);
cyl(bottle,0,0,0,.095,.105,.42,mat(0x668174,.24,.25),12);cyl(bottle,0,.235,0,.047,.06,.09,mat(0x718d7c,.28,.15),10);cyl(bottle,0,.29,0,.052,.052,.045,mats.oldMetal,10);
const water=new THREE.Mesh(new THREE.CylinderGeometry(.082,.09,.19,12),new THREE.MeshStandardMaterial({color:0x80b9ae,transparent:true,opacity:.45,roughness:.15}));water.position.y=-.09;bottle.add(water);
const hand=new THREE.Group();rig.add(hand);hand.position.set(.3,-.67,-.63);hand.rotation.z=-.16;
const sleeve=box(hand,0,-.15,0,.28,.46,.3,sleeveMat);const palm=sphere(hand,0,.12,0,.15,handMat,.86,.75,.72);for(let i=0;i<4;i++){const f=box(hand,-.1+i*.065,.24,.015,.045,.18,.065,handMat,-.16,0,0);f.castShadow=false}
rig.position.set(0,0,0);

