// ---------- Main loop ----------
const clock=new THREE.Clock();const forward=new THREE.Vector3(),right=new THREE.Vector3();
function findTarget(){raycaster.setFromCamera(center,camera);const objects=[];for(const r of residents)if(!r.healed){r.group.traverse(o=>{if(o.isMesh||o.isSprite)objects.push(o)})}const hit=raycaster.intersectObjects(objects,false)[0];let found=null;if(hit&&hit.distance<7.2){let o=hit.object;while(o&& !residents.some(r=>r.group===o))o=o.parent;if(o)found=residents.find(r=>r.group===o)||null}targetResident=found;ui.target.classList.toggle('visible',!!found&&!healing);ui.cross.classList.toggle('focus',!!found&&!healing);ui.healTouch.classList.toggle('ready',!!found&&!healing);if(found){ui.name.textContent=`${found.data.name} · “${found.data.need}”`} }
function update(dt,time){if(!isPlaying)return;
 camera.rotation.set(player.pitch,player.yaw,0,'YXZ');
 // A gentle body sway gives the first-person walk some weight
 let mx=(keys.KeyD?1:0)-(keys.KeyA?1:0),mz=(keys.KeyS?1:0)-(keys.KeyW?1:0);if(joy.active){mx=joy.x;mz=joy.y}const moving=Math.hypot(mx,mz)>.12&&!healing;
 if(moving){const length=Math.hypot(mx,mz);mx/=Math.max(1,length);mz/=Math.max(1,length);forward.set(-Math.sin(player.yaw),0,-Math.cos(player.yaw));right.set(Math.cos(player.yaw),0,-Math.sin(player.yaw));player.pos.addScaledVector(right,mx*player.speed*dt);player.pos.addScaledVector(forward,-mz*player.speed*dt);player.pos.x=THREE.MathUtils.clamp(player.pos.x,-6.5,6.6);player.pos.z=THREE.MathUtils.clamp(player.pos.z,-23.4,9.5);bob+=dt*9}
 camera.position.set(player.pos.x,player.pos.y+(moving?Math.sin(bob)*.035:0),player.pos.z);
